<!doctype html><html lang="es"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:10px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #aaa;padding:4px}h1{color:#173b70}</style></head><body><h1>Informe {{['daily'=>'diario de operación','weekly'=>'semanal de transporte','monthly'=>'mensual de gestión de transporte','executive'=>'ejecutivo de transporte'][$type]}}</h1><p>Período: {{$f['from']}} a {{$f['to']}} · Generado: {{now()->format('d/m/Y H:i')}}</p><table><tr><th>Programados</th><th>Cerrados</th><th>Cancelados</th><th>Interrumpidos</th><th>Ejecución</th><th>Puntualidad salida</th><th>Puntualidad llegada</th><th>Capacidad</th><th>Novedades</th></tr><tr><td>{{$summary['scheduled']}}</td><td>{{$summary['closed']}}</td><td>{{$summary['cancelled']}}</td><td>{{$summary['interrupted']}}</td><td>{{$summary['execution']===null?'N/A':$summary['execution'].' %'}}</td><td>{{$summary['departure_punctuality']===null?'N/A':$summary['departure_punctuality'].' %'}}</td><td>{{$summary['arrival_punctuality']===null?'N/A':$summary['arrival_punctuality'].' %'}}</td><td>{{$summary['capacity_utilization']===null?'N/A':$summary['capacity_utilization'].' %'}}</td><td>{{$summary['issues']}}</td></tr></table>@if($type!=='executive')<h2>Servicios</h2><table><tr><th>Fecha</th><th>Ruta</th><th>Programado</th><th>Real</th><th>Vehículo plan/real</th><th>Estado</th><th>Novedades</th></tr>@foreach($services as $s)<tr><td>{{$s->service_date->format('d/m/Y')}}</td><td>{{$s->route_name_snapshot}}</td><td>{{$s->scheduled_start_at->format('H:i')}}–{{$s->scheduled_arrival_at->format('H:i')}}</td><td>{{$s->actual_start_at?->format('H:i')??'—'}}–{{$s->actual_arrival_at?->format('H:i')??'—'}}</td><td>{{$s->vehicle?->plate??'—'}} / {{$s->actualVehicle?->plate??'—'}}</td><td>{{config('transport.service_statuses.'.$s->status,$s->status)}}</td><td>{{$s->issues->count()}}</td></tr>@endforeach</table>@endif</body></html>
